/* From Uiverse.io by vinodjangid07 - Tags: button, like, click effect */
.__UIV_SCOPE__ .Btn {
  width: 140px;
  height: 35px;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  border: none;
  border-radius: 5px;
  overflow: hidden;
  box-shadow: 5px 5px 10px rgba(0, 0, 0, 0.089);
  cursor: pointer;
  background-color: transparent;
}

.__UIV_SCOPE__ .leftContainer {
  width: 60%;
  height: 100%;
  background-color: rgb(238, 0, 0);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.__UIV_SCOPE__ .leftContainer .like {
  color: white;
  font-weight: 600;
}

.__UIV_SCOPE__ .likeCount {
  width: 40%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgb(238, 0, 0);
  font-weight: 600;
  position: relative;
  background-color: white;
}

.__UIV_SCOPE__ .likeCount::before {
  height: 8px;
  width: 8px;
  position: absolute;
  content: "";
  background-color: rgb(255, 255, 255);
  transform: rotate(45deg);
  left: -4px;
}

.__UIV_SCOPE__ .Btn:hover .leftContainer {
  background-color: rgb(219, 0, 0);
}

.__UIV_SCOPE__ .Btn:active .leftContainer {
  background-color: rgb(201, 0, 0);
}

.__UIV_SCOPE__ .Btn:active .leftContainer svg {
  transform: scale(1.15);
  transform-origin: top;
}
